    updates.push([`quote:${p.id}`,{...current,id:p.id,company:p.company,customer_id:p.fieldSalesCustomerId,confirmation:null,order:null,jobsite_id:p.jobsiteId,number:current?.number||'New quote',revision,selected_revision:revision,posting:[],snapshot:{...p,...calculateQuote(p,state.settings.companies),revision,jobsite:{id:site.id,name:site.name,address:site.address},companyProfiles:state.settings.companies},versions:[{revision},...(current?.versions||[]).filter(v=>v.revision!==revision)]}]);
  }
  if(kind==='note.add') {const site=await load('jobsite',p.jobsiteId);updates.push([`jobsite:${site.id}`,{...site,notes:[{id:p.id,body:p.body,actor_id:state.operator.id,created_at:new Date().toISOString()},...(site.notes||[])]}]);}
