}
async function reviewQueue() {
  const pending=await state.workspace.pending();
  const el=modal('Saved on this device',`<div class="banner">Pending work remains here until the server acknowledges it. Conflicting edits need your review.</div><div class="stack" style="margin-top:16px">${pending.map(e=>`<div class="record"><strong>${escape(e.kind==='photo'?'Visit photo':e.kind.replace('.',' '))}</strong><p>${escape(e.error||'Waiting to sync')}</p><small>${escape(e.createdAt)}</small><div class="actions"><button data-retry="${e.seq}" class="small">Retry</button>${e.kind==='quote.save'&&e.error?`<button data-fix-quote="${e.seq}" class="small">Review pending quote</button>`:''}${e.status===409&&['route.save','jobsite.save','customer.save','customerType.save'].includes(e.kind)?`<button data-review="${e.seq}" class="small">Review conflict</button>`:''}</div></div>`).join('')||'<p>No pending work.</p>'}</div>`,'<button id="export-work">Download recovery copy</button><button data-close>Close</button>');
