  on('[data-template-preview]','click',async(e,b)=>{const c=b.dataset.templatePreview,v=values(view.querySelector('#settings-form')),profile={...s.companies[c]};for(const [key] of companyFields){profile[key]=v[`${c}.${key}`];}profile.terms=v[`${c}.terms`];profile.taxBps=Math.round(Number(v[`${c}.taxPercent`])*100);profile.visible=Object.fromEntries(['expires','expectedClose','salesRep','shippingMethod','signature','barcode'].map(k=>[k,Boolean(v[`${c}.visible.${k}`])]));download(await ctx.api('/template-preview',{company:c,profile}),`${c}-quote-template.pdf`);},view);
